import { test } from "@e2e/fixtures";
import * as ui from "@e2e/ui-actions";

test.describe("Responsive All layout", () => {
  test.use({
    inspectorOptions: {
      inspectMode: true,
      viewport: { width: 1600, height: 900 },
    },
  });

  test("Resizing window across 1536px toggles All layout option visibility", async ({
    inspectorPage,
  }) => {
    await test.step("Start above breakpoint with All option visible", async () => {
      await inspectorPage.setViewportSize({ width: 1600, height: 900 });
      await ui.viewMenu.actions(inspectorPage).open();
      await ui.viewMenu.assertions(inspectorPage).allOptionIsVisible();
    });

    await test.step("Resize below breakpoint hides All option", async () => {
      await inspectorPage.setViewportSize({ width: 1240, height: 768 });
      await ui.viewMenu.actions(inspectorPage).open();
      await ui.viewMenu.assertions(inspectorPage).allOptionIsHidden();
    });

    await test.step("Resize above breakpoint shows All option again", async () => {
      await inspectorPage.setViewportSize({ width: 1600, height: 900 });
      await ui.viewMenu.actions(inspectorPage).open();
      await ui.viewMenu.assertions(inspectorPage).allOptionIsVisible();
    });
  });
});
